class Solution {
    public int heightChecker(int[] heights) {
        int[] counts = new int[101];
        for (int height : heights) {
            counts[height]++;
        }

        int expectedHeight = 1;
        int mismatches = 0;
        for (int height : heights) {
            while (counts[expectedHeight] == 0) {
                expectedHeight++;
            }
            if (height != expectedHeight) {
                mismatches++;
            }
            counts[expectedHeight]--;
        }
        return mismatches;
    }
}

import java.util.Arrays;

class Solution {
    public int heightChecker(int[] heights) {
        int[] expected = heights.clone();
        Arrays.sort(expected);
        int mismatches = 0;
        for (int i = 0; i < heights.length; i++) {
            if (heights[i] != expected[i]) {
                mismatches++;
            }
        }
        return mismatches;
    }
}

class Solution {
    public int heightChecker(int[] heights) {
        int[] expected = heights.clone();
        for (int i = 1; i < expected.length; i++) {
            int value = expected[i];
            int j = i - 1;
            while (j >= 0 && expected[j] > value) {
                expected[j + 1] = expected[j];
                j--;
            }
            expected[j + 1] = value;
        }

        int mismatches = 0;
        for (int i = 0; i < heights.length; i++) {
            if (heights[i] != expected[i]) {
                mismatches++;
            }
        }
        return mismatches;
    }
}

import java.util.Map;
import java.util.TreeMap;

class Solution {
    public int heightChecker(int[] heights) {
        TreeMap<Integer, Integer> frequencies = new TreeMap<>();
        for (int height : heights) {
            frequencies.put(height, frequencies.getOrDefault(height, 0) + 1);
        }

        int index = 0;
        int mismatches = 0;
        for (Map.Entry<Integer, Integer> entry : frequencies.entrySet()) {
            int height = entry.getKey();
            int times = entry.getValue();
            for (int count = 0; count < times; count++) {
                if (heights[index] != height) {
                    mismatches++;
                }
                index++;
            }
        }
        return mismatches;
    }
}

class Solution {
    public int heightChecker(int[] heights) {
        boolean[] used = new boolean[heights.length];
        int mismatches = 0;

        for (int expectedIndex = 0; expectedIndex < heights.length; expectedIndex++) {
            int bestIndex = -1;
            for (int i = 0; i < heights.length; i++) {
                if (!used[i] && (bestIndex == -1 || heights[i] < heights[bestIndex])) {
                    bestIndex = i;
                }
            }
            used[bestIndex] = true;
            if (heights[expectedIndex] != heights[bestIndex]) {
                mismatches++;
            }
        }
        return mismatches;
    }
}
